<?php namespace App\Repositories\MySQL; use App\Database\MySQLConnection; use App\Repositories\Interfaces\SkillRepositoryInterface;
final class MySQLSkillRepository implements SkillRepositoryInterface { public function __construct(private MySQLConnection $db){} public function all():array{return $this->db->pdo()->query('SELECT * FROM skills ORDER BY sort_order,name')->fetchAll();} public function find(string $id):?array{$s=$this->db->pdo()->prepare('SELECT * FROM skills WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;} public function save(array $d,?string $id=null):string{$p=$this->db->pdo();if($id){$s=$p->prepare('UPDATE skills SET name=?,category=?,proficiency=?,sort_order=? WHERE id=?');$s->execute([$d['name'],$d['category'],$d['proficiency'],(int)$d['sort_order'],$id]);return $id;}$s=$p->prepare('INSERT INTO skills(name,category,proficiency,sort_order) VALUES(?,?,?,?)');$s->execute([$d['name'],$d['category'],$d['proficiency'],(int)$d['sort_order']]);return (string)$p->lastInsertId();} public function delete(string $id):bool{$s=$this->db->pdo()->prepare('DELETE FROM skills WHERE id=?');return $s->execute([$id]);} public function count():int{return (int)$this->db->pdo()->query('SELECT COUNT(*) FROM skills')->fetchColumn();} }
